import {normalizeDoi,learningLevel} from './core.js?v=10';
const normalize=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const stop=new Set('de del el la los las un una y en sobre con para por como que quiero queremos estudiar estudio analizar comparar investigar proyecto experimento mediante utilizando usando voy vamos se al es son tengo hacer hago registrar registros the a an and or of in on with for to from i we want study investigate compare using research project experiment aim aims propose will would'.split(' '));
function words(s){return normalize(s).match(/[a-z0-9][a-z0-9+-]{1,}/g)?.filter(w=>!stop.has(w))||[]}
export function planSearch(text,mode='area',strict=false){const raw=text.trim();if(!raw)return {query:'',concepts:[]};const counts=new Map();words(raw).forEach(w=>counts.set(w,(counts.get(w)||0)+1));const terms=[...counts].sort((a,b)=>mode==='area'?0:b[1]-a[1]).slice(0,mode==='area'?20:14).map(([w])=>w);return {query:terms.join(mode==='experiment'&&!strict?' OR ':' '),concepts:terms.map(term=>({id:term,label:term})),fallback:false}}
export function matchConcepts(paper,selected){const text=new Set(words(paper.title+' '+(paper.abstract||'')+' '+(paper.keywords||'')));return selected.filter(c=>text.has(c.id))}
export function rebuildAbstract(index){const result=[];for(const [word,places]of Object.entries(index||{}))for(const pos of places)result[pos]=word;return result.filter(Boolean).join(' ')}
export function fromOpenAlex(record,strip=s=>String(s||'').replace(/<[^>]+>/g,' ')){
 if(!record.id||!record.title)return null;const primary=record.primary_topic,topic=primary?.id?{id:primary.id.split('/').pop(),label:primary.display_name}:undefined;
 const authors=(record.authorships||[]).map(a=>a.author?.display_name).filter(Boolean).map(name=>{const parts=name.trim().split(/\s+/);return parts.length>1?parts.pop()+', '+parts.join(' '):name}).join(' and ');
 return {id:'openalex-'+record.id.split('/').pop(),openAlexId:record.id,type:record.type||'article',title:strip(record.title),authors,year:String(record.publication_year||''),journal:record.primary_location?.source?.display_name||'',doi:normalizeDoi(record.doi||''),url:record.doi||record.primary_location?.landing_page_url||record.id,abstract:rebuildAbstract(record.abstract_inverted_index),keywords:(record.keywords||[]).map(k=>k.display_name).join(', '),topic,status:'Pendiente',notes:'',references:[],lookup:'unqueried',discoverySource:'OpenAlex',language:record.language||'',preprint:record.type==='preprint'};
}
export function samePaper(a,b){if(a.doi&&b.doi&&normalizeDoi(a.doi)===normalizeDoi(b.doi))return true;if(a.id===b.id)return true;const title=s=>normalize(s).replace(/[^a-z0-9]/g,'');return !!a.title&&title(a.title)===title(b.title)}

export function searchUrl(query,page='1'){const u=new URL('https://api.openalex.org/works');u.search=new URLSearchParams({search:query,filter:'language:en','per-page':'20',page:page==='*'?'1':page});return u.href}
export function isEnglishRecord(record){return ['en','eng','english'].includes(String(record.language||'').toLowerCase())}
export function translationChunks(text,maxBytes=440){const chunks=[];let current='';for(const word of text.trim().split(/\s+/)){if(new TextEncoder().encode(current+' '+word).length>maxBytes&&current){chunks.push(current);current=word}else current+=(current?' ':'')+word}if(current)chunks.push(current);return chunks}
export async function translateQuery(text,{signal,area=false,fetcher=fetch}={}){
 let source=text.replace(/\bbases\s+de\b/gi,'fundamentos de');const wrapped=area&&new TextEncoder().encode(source).length<300;if(wrapped)source='Estoy buscando publicaciones académicas sobre '+source+'.';const output=[];
 for(const chunk of translationChunks(source)){const u=new URL('https://api.mymemory.translated.net/get');u.search=new URLSearchParams({q:chunk,langpair:'es|en'});const response=await fetcher(u.href,{signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('No se pudo traducir la consulta. Escríbela en inglés y elige «Inglés».');const data=await response.json();if(Number(data.responseStatus)!==200||data.quotaFinished||!data.responseData?.translatedText)throw Error('El servicio de traducción no está disponible. Puedes escribir la consulta en inglés.');output.push(data.responseData.translatedText)}
 return output.join(' ').replace(/^I(?: am|'m) (?:looking|searching) for academic publications (?:on|about)\s*/i,'').replace(/\.$/,'').trim();
}
export function mergeDiscoveryBatch(existing,incoming){const papers=[...existing],ids=[];for(const paper of incoming){let known=papers.find(p=>samePaper(p,paper));if(!known){let id=paper.id,n=2;while(papers.some(p=>p.id===id))id=paper.id+'-'+n++;known={...paper,id};papers.push(known)}if(!ids.includes(known.id))ids.push(known.id)}return {papers,ids}}

export function learningSearchUrls(query){const intro=new URL(searchUrl(query)),advanced=new URL(searchUrl(query));intro.searchParams.set('search.title','(introduction OR fundamentals OR elementary OR tutorial OR basics OR primer OR foundations)');advanced.searchParams.set('search.title','(advanced OR applications OR frontiers OR recent advances)');return [intro.href,advanced.href]}
export function selectLearningPapers(candidates,count){const unique=[];for(const p of candidates)if(!unique.some(x=>samePaper(x,p)))unique.push(p);const buckets=[0,1,2,3].map(level=>unique.filter(p=>learningLevel(p).level===level));if(!buckets[0].length)return {papers:[],missingBasics:true};const selected=[],take=(level,n)=>{for(const p of buckets[level]){if(n<=0||selected.length>=count)break;if(!selected.includes(p)){selected.push(p);n--}}};take(0,Math.max(1,Math.ceil(count*.4)));take(1,Math.floor(count*.2));take(3,count>1?Math.max(1,Math.floor(count*.25)):0);for(const level of [2,1,3,0])take(level,count-selected.length);return {papers:selected.sort((a,b)=>learningLevel(a).level-learningLevel(b).level),missingBasics:false}}
